pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The buggy constructor reverts, so owner stays address(0).
        // The reference constructor sets owner = msg.sender (this test contract).
        // Try calling setOwner as the original deployer (address(this)).
        // On reference: succeeds because owner == address(this).
        // On buggy: revert because owner == address(0) != address(this).
        bool ok;
        try c.setOwner(address(0x123)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

