// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x123);
        vm.prank(alice);
        // The owner after deployment is msg.sender (this test contract)
        // We call setOwner to change owner to alice
        bool success;
        try c.setOwner(alice) { success = true; } catch { success = false; }
        assertTrue(success);
        // In the reference version, owner should be alice; in the buggy version, owner is msg.sender (the test contract)
        assertEq(c.owner(), alice);
    }
}

